-- Show all three peeked cards while selecting the matching color character.
UPDATE public.private_card_effect_catalog_v1 c
SET definitions = (
 SELECT coalesce(jsonb_agg(
   CASE
    WHEN e.value->>'effectId' IN ('card-0158-on-play-private-eye','card-0130-on-play-ladies-gentlemen')
    THEN (SELECT def FROM jsonb_array_elements($new_defs$[{"steps":[{"op":"peek_top_cards","count":3,"saveAs":"seen","allowFewer":true},{"op":"select_cards","max":1,"min":0,"from":"seen","filter":{"allOf":[{"field":"card_type","value":"character","operator":"equals"},{"field":"color","value":"yellow","operator":"equals"}]},"prompt":"공개하여 패에 추가할 황 캐릭터를 최대 1장 선택하세요.","saveAs":"selected","optional":true,"displayVariable":"seen"},{"op":"reveal_cards","to":["opponent"],"from":"selected","when":{"fact":"vars.selected.count","value":0,"operator":"greater_than"},"awaitAcknowledgement":true},{"op":"move_cards","to":"hand","from":"selected","when":{"fact":"vars.selected.count","value":0,"operator":"greater_than"}},{"op":"move_unselected_to_deck_bottom","from":"seen","order":"player_choice","selectedVariable":"selected"},{"op":"select_cards","max":1,"min":0,"from":"hand","filter":{"allOf":[{"field":"card_type","value":"character","operator":"equals"},{"field":"color","value":"yellow","operator":"equals"},{"field":"level","value":{"fact":"player.file.count"},"operator":"less_than_or_equal"}]},"prompt":"자신의 파일 수 이하 레벨인 황 캐릭터를 최대 1장 등장시킬 수 있습니다.","saveAs":"deployment","optional":true},{"op":"move_cards","to":"field","from":"deployment","when":{"fact":"vars.deployment.count","value":0,"operator":"greater_than"},"entryMethod":"event_effect"}],"cardIds":["0158"],"trigger":{"event":"event.played","timing":"after"},"effectId":"card-0158-on-play-private-eye","cardNameJa":"プライベート・アイ","cardNameKo":"프라이빗 아이","conditions":[],"reviewNotes":{"rationale":"덱에 적격 황 캐릭터가 없고 손패에도 등장 가능한 캐릭터가 없으면 검색한 카드만 손패에 넣고 이벤트 처리를 마친다.","sourceText":"덱 위 3장을 확인하고 황 캐릭터를 최대 1장 공개해 패에 추가한다. 나머지는 원하는 순서로 덱 아래에 둔 뒤 파일 수 이하 레벨의 황 캐릭터를 최대 1장 등장시킨다."}},{"steps":[{"op":"peek_top_cards","count":3,"saveAs":"seen","allowFewer":true},{"op":"select_cards","max":1,"min":0,"from":"seen","filter":{"allOf":[{"field":"card_type","value":"character","operator":"equals"},{"field":"color","value":"white","operator":"equals"}]},"prompt":"공개하여 패에 추가할 백 캐릭터를 최대 1장 선택하세요.","saveAs":"selected","optional":true,"displayVariable":"seen"},{"op":"reveal_cards","to":["opponent"],"from":"selected","when":{"fact":"vars.selected.count","value":0,"operator":"greater_than"},"awaitAcknowledgement":true},{"op":"move_cards","to":"hand","from":"selected","when":{"fact":"vars.selected.count","value":0,"operator":"greater_than"}},{"op":"move_unselected_to_deck_bottom","from":"seen","order":"player_choice","selectedVariable":"selected"},{"op":"select_cards","max":1,"min":0,"from":"hand","filter":{"allOf":[{"field":"card_type","value":"character","operator":"equals"},{"field":"color","value":"white","operator":"equals"},{"field":"level","value":{"fact":"player.file.count"},"operator":"less_than_or_equal"}]},"prompt":"자신의 파일 수 이하 레벨인 백 캐릭터를 최대 1장 등장시킬 수 있습니다.","saveAs":"deployment","optional":true},{"op":"move_cards","to":"field","from":"deployment","when":{"fact":"vars.deployment.count","value":0,"operator":"greater_than"},"entryMethod":"event_effect"}],"cardIds":["0130"],"trigger":{"event":"event.played","timing":"after"},"effectId":"card-0130-on-play-ladies-gentlemen","cardNameJa":"“Ladies♡ and… Gentlemen!!”","cardNameKo":"“Ladies♡ and… Gentlemen!!”","conditions":[],"reviewNotes":{"rationale":"프라이빗 아이와 같은 순서이며 대상 카드 색상만 백색으로 다르다.","sourceText":"덱 위 3장을 확인하고 백 캐릭터를 최대 1장 공개해 패에 추가한다. 나머지는 원하는 순서로 덱 아래에 둔 뒤 파일 수 이하 레벨의 백 캐릭터를 최대 1장 등장시킨다."}}]$new_defs$::jsonb) def WHERE def->>'effectId'=e.value->>'effectId')
    ELSE e.value
   END ORDER BY e.ordinality
 ),'[]'::jsonb)
 FROM jsonb_array_elements(coalesce(c.definitions,'[]'::jsonb)) WITH ORDINALITY e(value,ordinality)
),
updated_at=now()
WHERE c.catalog_id='main';
